function ago(iso, now) {
  const t = iso ? Date.parse(iso) : Number.NaN;
  if (!Number.isFinite(t))
    return "recently";
  const s2 = Math.max(0, (now - t) / 1000);
  if (s2 < 45)
    return "just now";
  if (s2 < 90)
    return "1 minute ago";
  if (s2 < 45 * 60)
    return `${Math.round(s2 / 60)} minutes ago`;
  if (s2 < 90 * 60)
    return "1 hour ago";
  if (s2 < 22 * 3600)
    return `${Math.round(s2 / 3600)} hours ago`;
  if (s2 < 36 * 3600)
    return "yesterday";
  if (s2 < 26 * 86400)
    return `${Math.round(s2 / 86400)} days ago`;
  const d = new Date(t);
  const sameYear = d.getUTCFullYear() === new Date(now).getUTCFullYear();
  return `on ${d.toLocaleDateString("en-US", { month: "short", day: "numeric", ...sameYear ? {} : { year: "numeric" }, timeZone: "UTC" })}`;
}
